from pricing import quote
# Check float semantics against original expressions
def orig(kind, amount):
    if kind == 'regular': return round(amount * 1.2, 2)
    if kind == 'member': return round(amount * 0.9 * 1.2, 2)
    if kind == 'staff': return round(amount * 0.8 * 1.2, 2)
    raise ValueError('unknown kind')
import random
random.seed(42)
for _ in range(20000):
    k = random.choice(['regular','member','staff'])
    a = random.uniform(-1e6, 1e6)
    if orig(k, a) != quote(k, a):
        print('MISMATCH', k, a, orig(k,a), quote(k,a)); break
else:
    print('all match')
# edge: exact 0.9*1.2 vs 0.9*1.2
print(0.9*1.2, 0.8*1.2)
# verify ValueError message
try:
    quote('other', 10)
except ValueError as e:
    print('msg:', repr(str(e)))
"

